{
  "name": "Curriculum Analysis Table Generator",
  "description": "A comprehensive tool to create and calculate educational curriculum analysis tables (Table 1, Normalized Table to 100, and Question Count Table to 60) with automatic priority ranking and sum adjustments.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Behavior {
  id: string;
  name: string;
  isCognitive: boolean; // Table 2 only includes Cognitive Domain (พุทธพิสัย)
}

export interface Unit {
  id: string;
  name: string;
  periods: number;
}

export interface CurriculumMetadata {
  code: string;
  subject: string;
  credits: string;
  level: string;
  branch: string;
}

export type MatrixData = Record<string, Record<string, number>>;

/**
 * Calculates priority rankings based on values.
 * Highest value gets rank 1.
 * Same values get the same rank.
 */
export const calculatePriority = (values: number[]): (number | string)[] => {
  if (values.length === 0) return [];

  // Filter out zeros or nulls if they shouldn't be ranked
  const validValues = values.filter(v => v > 0);
  if (validValues.length === 0) return values.map(() => '-');

  const sortedUnique = Array.from(new Set(validValues)).sort((a, b) => b - a);

  return values.map(v => {
    if (v === 0) return '-';
    const rank = sortedUnique.indexOf(v) + 1;
    // According to prompt, rank should be 1-10. We'll cap it just in case.
    return rank > 10 ? 10 : rank;
  });
};

/**
 * Distributes a target sum across an array of values using the Largest Remainder Method
 * to ensure the sum is exactly the target after rounding.
 */
export const distributeSum = (values: number[], targetSum: number): number[] => {
  const currentTotal = values.reduce((a, b) => a + b, 0);
  if (currentTotal === 0) return values.map(() => 0);

  const scaled = values.map(v => (v * targetSum) / currentTotal);
  const floors = scaled.map(v => Math.floor(v));
  const remainders = scaled.map((v, i) => v - floors[i]);

  let currentSum = floors.reduce((a, b) => a + b, 0);
  const diff = targetSum - currentSum;

  // Create indexed remainders to track positions
  const indexedRemainders = remainders.map((r, i) => ({ r, i }));
  indexedRemainders.sort((a, b) => b.r - a.r);

  // Distribute the difference to those with the largest remainders
  for (let i = 0; i < diff; i++) {
    floors[indexedRemainders[i].i]++;
  }

  return floors;
};

/**
 * Scales a 2D matrix to a specific target grand total while maintaining 
 * integer values and ensuring row/column sums match the adjusted grand total.
 */
export const scaleMatrix = (
  matrix: number[][],
  targetTotal: number
): number[][] => {
  const flat = matrix.flat();
  const adjustedFlat = distributeSum(flat, targetTotal);

  const result: number[][] = [];
  let pointer = 0;
  for (let r = 0; r < matrix.length; r++) {
    const row: number[] = [];
    for (let c = 0; c < matrix[r].length; c++) {
      row.push(adjustedFlat[pointer++]);
    }
    result.push(row);
  }
  return result;
};

import React, { useState, useMemo, useCallback } from 'react';
import { Behavior, Unit, MatrixData, CurriculumMetadata } from './types';
import { calculatePriority, scaleMatrix } from './utils/calculations';

// Initial data for easy start
const INITIAL_BEHAVIORS: Behavior[] = [
  { id: 'b1', name: 'ความรู้', isCognitive: true },
  { id: 'b2', name: 'ความเข้าใจ', isCognitive: true },
  { id: 'b3', name: 'นำไปใช้', isCognitive: true },
  { id: 'b4', name: 'วิเคราะห์', isCognitive: true },
  { id: 'b5', name: 'ประเมินค่า', isCognitive: true },
  { id: 'b6', name: 'สร้างสรรค์', isCognitive: true },
  { id: 'b7', name: 'ทักษะพิสัย', isCognitive: false },
  { id: 'b8', name: 'จิตพิสัย', isCognitive: false },
  { id: 'b9', name: 'ประยุกต์ใช้', isCognitive: false },
];

const App: React.FC = () => {
  const [metadata, setMetadata] = useState<CurriculumMetadata>({
    code: '21910-2010',
    subject: 'การเขียนภาษาโปรแกรมคอมพิวเตอร์',
    credits: '3 หน่วยกิต',
    level: 'ปวช. 2',
    branch: 'เทคโนโลยีธุรกิจดิจิทัล /สมรรถนะวิชาชีพเฉพาะ'
  });

  const [behaviors, setBehaviors] = useState<Behavior[]>(INITIAL_BEHAVIORS);
  const [units, setUnits] = useState<Unit[]>([
    { id: 'u1', name: '1. พื้นฐานการเขียนโปรแกรมเชิงธุรกิจ', periods: 12 },
    { id: 'u2', name: '2. การประมวลผลข้อมูลและการตัดสินใจ', periods: 12 },
  ]);

  const [matrix, setMatrix] = useState<MatrixData>({});

  const handleCellChange = (unitId: string, behaviorId: string, val: string) => {
    const num = parseInt(val);
    if (isNaN(num)) {
      setMatrix(prev => {
        const next = { ...prev };
        if (next[unitId]) delete next[unitId][behaviorId];
        return next;
      });
      return;
    }
    // Limit 1-10
    const clamped = Math.min(10, Math.max(1, num));
    setMatrix(prev => ({
      ...prev,
      [unitId]: {
        ...(prev[unitId] || {}),
        [behaviorId]: clamped
      }
    }));
  };

  const addUnit = () => {
    const id = `u${Date.now()}`;
    setUnits([...units, { id, name: `หน่วยที่ ${units.length + 1}`, periods: 0 }]);
  };

  const addBehavior = () => {
    const id = `b${Date.now()}`;
    const name = prompt('ชื่อพฤติกรรม:');
    if (name) {
      setBehaviors([...behaviors, { id, name, isCognitive: true }]);
    }
  };

  const removeUnit = (id: string) => setUnits(units.filter(u => u.id !== id));
  const removeBehavior = (id: string) => setBehaviors(behaviors.filter(b => b.id !== id));

  // --- TABLE 1 CALCULATIONS ---
  const table1Rows = useMemo(() => {
    return units.map(unit => {
      const rowData = behaviors.map(b => matrix[unit.id]?.[b.id] || 0);
      const rowSum = rowData.reduce((a, b) => a + b, 0);
      return { unit, data: rowData, sum: rowSum };
    });
  }, [units, behaviors, matrix]);

  const table1ColSums = useMemo(() => {
    return behaviors.map(b => {
      return units.reduce((sum, u) => sum + (matrix[u.id]?.[b.id] || 0), 0);
    });
  }, [units, behaviors, matrix]);

  const table1GrandTotal = table1ColSums.reduce((a, b) => a + b, 0);

  const table1RowPriorities = calculatePriority(table1Rows.map(r => r.sum));
  const table1ColPriorities = calculatePriority(table1ColSums);

  // --- TABLE 2 CALCULATIONS (Scale to 100) ---
  const table2Behaviors = behaviors.filter(b => b.isCognitive);
  const table2Data = useMemo(() => {
    if (table1GrandTotal === 0) return [];

    // Extract raw numbers from Table 1 for cognitive behaviors only
    const rawMatrix: number[][] = units.map(u => 
      table2Behaviors.map(b => matrix[u.id]?.[b.id] || 0)
    );

    return scaleMatrix(rawMatrix, 100);
  }, [units, table2Behaviors, matrix, table1GrandTotal]);

  const table2Rows = useMemo(() => {
    return units.map((unit, i) => {
      const rowData = table2Data[i] || table2Behaviors.map(() => 0);
      const sum = rowData.reduce((a, b) => a + b, 0);
      return { unit, data: rowData, sum };
    });
  }, [units, table2Behaviors, table2Data]);

  const table2ColSums = useMemo(() => {
    return table2Behaviors.map((_, colIdx) => {
      return table2Data.reduce((sum, row) => sum + row[colIdx], 0);
    });
  }, [table2Behaviors, table2Data]);

  const table2RowPriorities = calculatePriority(table2Rows.map(r => r.sum));
  const table2ColPriorities = calculatePriority(table2ColSums);

  // --- TABLE 3 CALCULATIONS (Scale to 60) ---
  const table3Data = useMemo(() => {
    if (table2Data.length === 0) return [];
    return scaleMatrix(table2Data, 60);
  }, [table2Data]);

  const table3Rows = useMemo(() => {
    return units.map((unit, i) => {
      const rowData = table3Data[i] || table2Behaviors.map(() => 0);
      const sum = rowData.reduce((a, b) => a + b, 0);
      return { unit, data: rowData, sum };
    });
  }, [units, table2Behaviors, table3Data]);

  const table3ColSums = useMemo(() => {
    return table2Behaviors.map((_, colIdx) => {
      return table3Data.reduce((sum, row) => sum + row[colIdx], 0);
    });
  }, [table2Behaviors, table3Data]);

  const table3RowPriorities = calculatePriority(table3Rows.map(r => r.sum));
  const table3ColPriorities = calculatePriority(table3ColSums);

  return (
