          ระบบสร้างตารางวิเคราะห์หลักสูตร
        </h1>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-8">
          <div>
            <label className="block text-sm font-medium text-gray-700">รหัสวิชา</label>
            <input type="text" className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 border" value={metadata.code} onChange={e => setMetadata({...metadata, code: e.target.value})} />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">ชื่อวิชา</label>
            <input type="text" className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 border" value={metadata.subject} onChange={e => setMetadata({...metadata, subject: e.target.value})} />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">หน่วยกิต</label>
            <input type="text" className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 border" value={metadata.credits} onChange={e => setMetadata({...metadata, credits: e.target.value})} />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">ชั้น</label>
            <input type="text" className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 border" value={metadata.level} onChange={e => setMetadata({...metadata, level: e.target.value})} />
          </div>
          <div className="lg:col-span-2">
            <label className="block text-sm font-medium text-gray-700">สาขาวิชา/กลุ่มวิชา</label>
            <input type="text" className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 border" value={metadata.branch} onChange={e => setMetadata({...metadata, branch: e.target.value})} />
          </div>
        </div>

        <div className="flex flex-wrap gap-4">
          <button onClick={addUnit} className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition flex items-center gap-2">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4"></path></svg>
            เพิ่มชื่อหน่วย
          </button>
          <button onClick={addBehavior} className="bg-emerald-600 text-white px-4 py-2 rounded-lg hover:bg-emerald-700 transition flex items-center gap-2">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4"></path></svg>
            เพิ่มพฤติกรรม
          </button>
          <button onClick={() => window.print()} className="bg-gray-800 text-white px-4 py-2 rounded-lg hover:bg-gray-900 transition flex items-center gap-2">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
            พิมพ์
          </button>
        </div>
      </section>

      {/* TABLE 1: Main Table */}
      <div className="bg-white p-6 rounded-xl shadow-md border border-gray-200 overflow-x-auto">
        <div className="text-center mb-6">
          <h2 className="text-xl font-bold">ตารางวิเคราะห์หลักสูตร</h2>
          <div className="grid grid-cols-3 text-left mt-4 text-sm gap-y-1">
             <p>รหัส {metadata.code}</p>
             <p>วิชา {metadata.subject}</p>
             <p>หน่วยกิต {metadata.credits}</p>
             <p>ชั้น {metadata.level}</p>
             <p className="col-span-2">สาขาวิชา/กลุ่มวิชา {metadata.branch}</p>
          </div>
        </div>

        <table className="w-full border-collapse border border-gray-400 text-sm text-center">
          <thead>
            <tr className="bg-gray-100">
              <th rowSpan={3} className="border border-gray-400 p-2 min-w-[200px]">ชื่อหน่วย</th>
              <th colSpan={behaviors.length} className="border border-gray-400 p-2">พฤติกรรม</th>
              <th rowSpan={3} className="border border-gray-400 p-2 w-16">รวม</th>
              <th rowSpan={3} className="border border-gray-400 p-2 w-16">ลำดับความสำคัญ</th>
              <th rowSpan={3} className="border border-gray-400 p-2 w-16">จำนวนคาบ</th>
            </tr>
            <tr className="bg-gray-100">
               {/* Simplified header logic as per requirement: behaviors grouping can be complex, showing flat for now */}
               <th colSpan={behaviors.length} className="border border-gray-400 p-1">พุทธพิสัย/ทักษะพิสัย/จิตพิสัย</th>
            </tr>
            <tr className="bg-gray-50">
              {behaviors.map(b => (
                <th key={b.id} className="border border-gray-400 p-1 font-normal text-[10px] vertical-text h-32 relative group">
                  <div className="transform -rotate-90 origin-center absolute inset-0 flex items-center justify-center whitespace-nowrap">
                    {b.name}
                  </div>
                  <button onClick={() => removeBehavior(b.id)} className="absolute top-0 right-0 p-1 text-red-500 opacity-0 group-hover:opacity-100 no-print">×</button>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {table1Rows.map((row, rIdx) => (
              <tr key={row.unit.id}>
                <td className="border border-gray-400 p-2 text-left relative group">
                  <input 
                    type="text" 
                    className="w-full bg-transparent border-none focus:ring-0 p-0 text-left" 
                    value={row.unit.name} 
                    onChange={e => {
                      const newUnits = [...units];
                      newUnits[rIdx].name = e.target.value;
                      setUnits(newUnits);
                    }} 
                  />
                  <button onClick={() => removeUnit(row.unit.id)} className="absolute right-0 top-1/2 -translate-y-1/2 text-red-400 p-1 opacity-0 group-hover:opacity-100 no-print">×</button>
                </td>
                {behaviors.map((b, bIdx) => (
                  <td key={b.id} className="border border-gray-400 p-1">
                    <input
                      type="number"
                      min="1"
                      max="10"
                      className="w-full text-center border-none focus:ring-0 p-0"
                      value={matrix[row.unit.id]?.[b.id] || ''}
                      onChange={e => handleCellChange(row.unit.id, b.id, e.target.value)}
                    />
                  </td>
                ))}
                <td className="border border-gray-400 p-2 font-bold bg-gray-50">{row.sum || '-'}</td>
                <td className="border border-gray-400 p-2 font-bold bg-blue-50">{table1RowPriorities[rIdx]}</td>
                <td className="border border-gray-400 p-2">
                  <input
                    type="number"
                    className="w-full text-center border-none focus:ring-0 p-0"
                    value={row.unit.periods || ''}
                    onChange={e => {
                      const newUnits = [...units];
                      newUnits[rIdx].periods = parseInt(e.target.value) || 0;
                      setUnits(newUnits);
                    }}
                  />
                </td>
              </tr>
            ))}
            <tr className="bg-gray-100 font-bold">
              <td className="border border-gray-400 p-2">รวม</td>
              {table1ColSums.map((sum, i) => (
                <td key={behaviors[i].id} className="border border-gray-400 p-2">{sum || '-'}</td>
              ))}
              <td className="border border-gray-400 p-2 bg-yellow-50">{table1GrandTotal || '-'}</td>
              <td colSpan={2} className="border border-gray-400 bg-gray-100"></td>
            </tr>
            <tr className="bg-gray-100 font-bold">
              <td className="border border-gray-400 p-2">ลำดับความสำคัญ</td>
              {table1ColPriorities.map((p, i) => (
                <td key={behaviors[i].id} className="border border-gray-400 p-2 text-indigo-700">{p}</td>
              ))}
              <td colSpan={3} className="border border-gray-400"></td>
            </tr>
          </tbody>
        </table>
      </div>

      {/* TABLE 2: Adjusted Weight to 100 */}
      <div className="bg-white p-6 rounded-xl shadow-md border border-gray-200 overflow-x-auto print-break">
        <div className="text-center mb-6">
          <h2 className="text-xl font-bold">ตารางวิเคราะห์หลักสูตร (ปรับคะแนนน้ำหนักให้เป็น 100)</h2>
          <div className="grid grid-cols-3 text-left mt-4 text-sm gap-y-1">
             <p>รหัส {metadata.code}</p>
             <p>วิชา {metadata.subject}</p>
             <p>หน่วยกิต {metadata.credits}</p>
             <p>ชั้น {metadata.level}</p>
             <p className="col-span-2">สาขาวิชา/กลุ่มวิชา {metadata.branch}</p>
          </div>
        </div>

        <table className="w-full border-collapse border border-gray-400 text-sm text-center">
          <thead>
             <tr className="bg-gray-100">
                <th rowSpan={2} className="border border-gray-400 p-2">ชื่อหน่วย</th>
                <th colSpan={table2Behaviors.length} className="border border-gray-400 p-2">พุทธพิสัย</th>
                <th rowSpan={2} className="border border-gray-400 p-2 w-16">รวม</th>
                <th rowSpan={2} className="border border-gray-400 p-2 w-16 text-[10px]">ลำดับความสำคัญ</th>
                <th rowSpan={2} className="border border-gray-400 p-2 w-16">จำนวนคาบ</th>
             </tr>
             <tr className="bg-gray-50">
               {table2Behaviors.map(b => (
                 <th key={b.id} className="border border-gray-400 p-1 font-normal text-[10px] vertical-text h-24">
                   <div className="transform -rotate-90 origin-center absolute inset-0 flex items-center justify-center whitespace-nowrap">
                    {b.name}
                  </div>
                 </th>
               ))}
             </tr>
          </thead>
          <tbody>
            {table2Rows.map((row, rIdx) => (
              <tr key={row.unit.id}>
                <td className="border border-gray-400 p-2 text-left">{row.unit.name}</td>
                {row.data.map((val, bIdx) => (
                  <td key={bIdx} className="border border-gray-400 p-1">{val || '-'}</td>
                ))}
                <td className="border border-gray-400 p-2 font-bold bg-gray-50">{row.sum}</td>
                <td className="border border-gray-400 p-2 font-bold bg-blue-50">{table2RowPriorities[rIdx]}</td>
                <td className="border border-gray-400 p-2">{row.unit.periods}</td>
              </tr>
            ))}
            <tr className="bg-gray-100 font-bold">
               <td className="border border-gray-400 p-2">รวม</td>
               {table2ColSums.map((sum, i) => (
                 <td key={i} className="border border-gray-400 p-2">{sum}</td>
               ))}
               <td className="border border-gray-400 p-2 bg-yellow-100">100</td>
               <td colSpan={2} className="border border-gray-400"></td>
            </tr>
            <tr className="bg-gray-100 font-bold">
              <td className="border border-gray-400 p-2">ลำดับความสำคัญ</td>
              {table2ColPriorities.map((p, i) => (
                <td key={i} className="border border-gray-400 p-2 text-indigo-700">{p}</td>
              ))}
              <td colSpan={3} className="border border-gray-400"></td>
            </tr>
          </tbody>
        </table>
      </div>

      {/* TABLE 3: Question Counts to 60 */}
