             <p>ชั้น {metadata.level}</p>
             <p className="col-span-2">สาขาวิชา/กลุ่มวิชา {metadata.branch}</p>
          </div>
        </div>

        <table className="w-full border-collapse border border-gray-400 text-sm text-center">
          <thead>
             <tr className="bg-gray-100">
                <th rowSpan={2} className="border border-gray-400 p-2">ชื่อหน่วย</th>
                <th colSpan={table2Behaviors.length} className="border border-gray-400 p-2">พุทธพิสัย</th>
