          ระบบสร้างตารางวิเคราะห์หลักสูตร
        </h1>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-8">
          <div>
            <label className="block text-sm font-semibold text-black">รหัสวิชา</label>
            <input type="text" className="mt-1 block w-full rounded-md border-gray-400 bg-white text-black shadow-sm focus:border-black focus:ring-black sm:text-sm p-2 border" value={metadata.code} onChange={e => setMetadata({...metadata, code: e.target.value})} />
          </div>
          <div>
            <label className="block text-sm font-semibold text-black">ชื่อวิชา</label>
            <input type="text" className="mt-1 block w-full rounded-md border-gray-400 bg-white text-black shadow-sm focus:border-black focus:ring-black sm:text-sm p-2 border" value={metadata.subject} onChange={e => setMetadata({...metadata, subject: e.target.value})} />
          </div>
          <div>
            <label className="block text-sm font-semibold text-black">หน่วยกิต</label>
            <input type="text" className="mt-1 block w-full rounded-md border-gray-400 bg-white text-black shadow-sm focus:border-black focus:ring-black sm:text-sm p-2 border" value={metadata.credits} onChange={e => setMetadata({...metadata, credits: e.target.value})} />
          </div>
          <div>
            <label className="block text-sm font-semibold text-black">ชั้น</label>
            <input type="text" className="mt-1 block w-full rounded-md border-gray-400 bg-white text-black shadow-sm focus:border-black focus:ring-black sm:text-sm p-2 border" value={metadata.level} onChange={e => setMetadata({...metadata, level: e.target.value})} />
          </div>
          <div className="lg:col-span-2">
            <label className="block text-sm font-semibold text-black">สาขาวิชา/กลุ่มวิชา</label>
            <input type="text" className="mt-1 block w-full rounded-md border-gray-400 bg-white text-black shadow-sm focus:border-black focus:ring-black sm:text-sm p-2 border" value={metadata.branch} onChange={e => setMetadata({...metadata, branch: e.target.value})} />
          </div>
        </div>

        <div className="flex flex-wrap gap-4">
