            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4"></path></svg>
            เพิ่มชื่อหน่วย
          </button>
          <button onClick={addBehavior} className="bg-white text-black border border-black px-4 py-2 rounded-lg hover:bg-gray-100 transition flex items-center gap-2 shadow-sm">
