              <label className="text-xs font-bold uppercase tracking-wider text-black/40 px-1">รหัสวิชา</label>
              <input type="text" className="w-full bg-white border border-black/10 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-black transition-all font-bold" value={metadata.code} onChange={e => setMetadata({...metadata, code: e.target.value})} />
