import React, { useState, useMemo } from 'react';
import { Behavior, Unit, MatrixData, CurriculumMetadata } from './types';
import { calculatePriority, scaleMatrix } from './utils/calculations';

// Initial data for easy start
const INITIAL_BEHAVIORS: Behavior[] = [
  { id: 'b1', name: 'ความรู้ (Knowledge)', isCognitive: true },
  { id: 'b2', name: 'ความเข้าใจ (Comprehension)', isCognitive: true },
  { id: 'b3', name: 'นำไปใช้ (Application)', isCognitive: true },
  { id: 'b4', name: 'วิเคราะห์ (Analysis)', isCognitive: true },
  { id: 'b5', name: 'ประเมินค่า (Evaluation)', isCognitive: true },
  { id: 'b6', name: 'สร้างสรรค์ (Creation)', isCognitive: true },
  { id: 'b7', name: 'ทักษะพิสัย (Psychomotor)', isCognitive: false },
  { id: 'b8', name: 'จิตพิสัย (Affective)', isCognitive: false },
  { id: 'b9', name: 'ประยุกต์ใช้ (Integration)', isCognitive: false },
];

const App: React.FC = () => {
  const [metadata, setMetadata] = useState<CurriculumMetadata>({
    code: '21910-2010',
    subject: 'การเขียนภาษาโปรแกรมคอมพิวเตอร์',
    credits: '3 หน่วยกิต',
    level: 'ปวช. 2',
    branch: 'เทคโนโลยีธุรกิจดิจิทัล / สมรรถนะวิชาชีพเฉพาะ'
  });

  const [behaviors, setBehaviors] = useState<Behavior[]>(INITIAL_BEHAVIORS);
  const [units, setUnits] = useState<Unit[]>([
    { id: 'u1', name: '1. พื้นฐานการเขียนโปรแกรมเชิงธุรกิจ', periods: 12 },
    { id: 'u2', name: '2. การประมวลผลข้อมูลและการตัดสินใจ', periods: 12 },
  ]);

  const [matrix, setMatrix] = useState<MatrixData>({});

  const handleCellChange = (unitId: string, behaviorId: string, val: string) => {
    const num = parseInt(val);
    if (isNaN(num)) {
      setMatrix(prev => {
        const next = { ...prev };
        if (next[unitId]) {
          const row = { ...next[unitId] };
          delete row[behaviorId];
          next[unitId] = row;
        }
        return next;
      });
      return;
    }
    const clamped = Math.min(10, Math.max(1, num));
    setMatrix(prev => ({
      ...prev,
      [unitId]: {
        ...(prev[unitId] || {}),
        [behaviorId]: clamped
      }
    }));
  };

  const addUnit = () => {
    const id = `u${Date.now()}`;
    setUnits([...units, { id, name: `หน่วยที่ ${units.length + 1}. `, periods: 0 }]);
  };

  const addBehavior = () => {
    const id = `b${Date.now()}`;
    const name = prompt('กรุณาระบุชื่อพฤติกรรม:');
    if (name) {
      setBehaviors([...behaviors, { id, name, isCognitive: true }]);
    }
  };

  const clearMatrix = () => {
    if (confirm('ยืนยันการลบข้อมูลตัวเลขทั้งหมดในตาราง?')) {
      setMatrix({});
    }
  };

  const removeUnit = (id: string) => {
    if(confirm('ลบหน่วยการเรียนรู้นี้?')) setUnits(units.filter(u => u.id !== id));
  };
  const removeBehavior = (id: string) => {
    if(confirm('ลบพฤติกรรมนี้?')) setBehaviors(behaviors.filter(b => b.id !== id));
  };

  // --- CALCULATIONS ---
  const table1Rows = useMemo(() => units.map(unit => {
    const rowData = behaviors.map(b => matrix[unit.id]?.[b.id] || 0);
    const rowSum = rowData.reduce((a, b) => a + b, 0);
    return { unit, data: rowData, sum: rowSum };
  }), [units, behaviors, matrix]);

  const table1ColSums = useMemo(() => behaviors.map(b => units.reduce((sum, u) => sum + (matrix[u.id]?.[b.id] || 0), 0)), [units, behaviors, matrix]);
  const table1GrandTotal = table1ColSums.reduce((a, b) => a + b, 0);
  const table1RowPriorities = calculatePriority(table1Rows.map(r => r.sum));
  const table1ColPriorities = calculatePriority(table1ColSums);

  const table2Behaviors = behaviors.filter(b => b.isCognitive);
  const table2Data = useMemo(() => {
    if (table1GrandTotal === 0) return units.map(() => table2Behaviors.map(() => 0));
    const rawMatrix = units.map(u => table2Behaviors.map(b => matrix[u.id]?.[b.id] || 0));
    return scaleMatrix(rawMatrix, 100, 10);
  }, [units, table2Behaviors, matrix, table1GrandTotal]);

  const table2Rows = useMemo(() => units.map((unit, i) => {
    const rowData = table2Data[i] || table2Behaviors.map(() => 0);
    return { unit, data: rowData, sum: rowData.reduce((a, b) => a + b, 0) };
  }), [units, table2Behaviors, table2Data]);

  const table2ColSums = useMemo(() => table2Behaviors.map((_, colIdx) => table2Data.reduce((sum, row) => sum + row[colIdx], 0)), [table2Behaviors, table2Data]);
  const table2RowPriorities = calculatePriority(table2Rows.map(r => r.sum));
  const table2ColPriorities = calculatePriority(table2ColSums);

  const table3Data = useMemo(() => table2Data.length ? scaleMatrix(table2Data, 60) : [], [table2Data]);
  const table3Rows = useMemo(() => units.map((unit, i) => {
    const rowData = table3Data[i] || table2Behaviors.map(() => 0);
    return { unit, data: rowData, sum: rowData.reduce((a, b) => a + b, 0) };
  }), [units, table2Behaviors, table3Data]);

  const table3ColSums = useMemo(() => table2Behaviors.map((_, colIdx) => table3Data.reduce((sum, row) => sum + row[colIdx], 0)), [table2Behaviors, table3Data]);
  const table3RowPriorities = calculatePriority(table3Rows.map(r => r.sum));
  const table3ColPriorities = calculatePriority(table3ColSums);

  return (
    <div className="min-h-screen bg-white text-black font-['Sarabun'] antialiased py-8 px-4 md:px-12">
      <div className="max-w-[1400px] mx-auto space-y-12">

        {/* Header Section */}
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 no-print border-b border-black pb-8">
          <div className="space-y-2">
            <h1 className="text-4xl font-extrabold tracking-tight">ระบบวิเคราะห์หลักสูตร</h1>
            <p className="text-gray-500 font-medium">จัดการภาระงานและวิเคราะห์สัดส่วนข้อสอบอัตโนมัติ</p>
          </div>
          <div className="flex flex-wrap gap-3">
            <button onClick={() => window.print()} className="bg-black text-white px-8 py-3 rounded-full font-bold hover:bg-gray-800 transition shadow-lg flex items-center gap-2">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
              พิมพ์รายงาน
            </button>
          </div>
        </header>

        {/* Info Card Panel */}
        <section className="bg-gray-50 rounded-3xl p-8 space-y-8 no-print border border-gray-100 shadow-sm">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-x-8 gap-y-6">
            {[
              { label: 'รหัสวิชา', key: 'code' },
              { label: 'ชื่อวิชา', key: 'subject', span: 'lg:col-span-2' },
              { label: 'หน่วยกิต', key: 'credits' },
              { label: 'ระดับชั้น', key: 'level' },
              { label: 'สาขาวิชา / สมรรถนะวิชาชีพ', key: 'branch', span: 'lg:col-span-3' },
            ].map((field) => (
              <div key={field.key} className={`${field.span || ''} space-y-1`}>
                <label className="text-[11px] font-black uppercase tracking-widest text-gray-400 ml-1">{field.label}</label>
                <input 
                  type="text" 
                  className="w-full bg-white border border-gray-200 rounded-2xl px-5 py-3.5 focus:border-black focus:ring-1 focus:ring-black outline-none transition font-bold text-gray-800"
                  value={(metadata as any)[field.key]} 
                  onChange={e => setMetadata({...metadata, [field.key]: e.target.value})} 
                />
              </div>
            ))}
          </div>

          <div className="flex flex-wrap items-center gap-4 pt-6 border-t border-gray-200">
            <button onClick={addUnit} className="px-6 py-3 bg-white border-2 border-black rounded-2xl font-black hover:bg-black hover:text-white transition flex items-center gap-2">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4"></path></svg>
              เพิ่มหน่วย
            </button>
            <button onClick={addBehavior} className="px-6 py-3 bg-white border-2 border-black rounded-2xl font-black hover:bg-black hover:text-white transition flex items-center gap-2">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4"></path></svg>
              เพิ่มพฤติกรรม
            </button>
            <div className="flex-1"></div>
            <button onClick={clearMatrix} className="px-6 py-3 border-2 border-red-500 text-red-500 rounded-2xl font-black hover:bg-red-500 hover:text-white transition flex items-center gap-2">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
              ล้างข้อมูลตัวเลข
            </button>
          </div>
        </section>

        {/* Main Content Area */}
        <div className="space-y-24">

          {/* Table 1 Card */}
          <div className="space-y-8">
            <div className="text-center space-y-2">
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-400 bg-gray-100 px-4 py-1.5 rounded-full">ตารางที่ 1</span>
              <h2 className="text-3xl font-black">ตารางวิเคราะห์หลักสูตร</h2>
