                  value={(metadata as any)[field.key]} 
                  onChange={e => setMetadata({...metadata, [field.key]: e.target.value})} 
                />
              </div>
            ))}
          </div>

          <div className="flex flex-wrap items-center gap-3 pt-6 border-t border-slate-100">
            <button type="button" onClick={addUnit} className="px-6 py-3 bg-indigo-50 text-indigo-700 rounded-2xl font-bold hover:bg-indigo-600 hover:text-white transition-all flex items-center gap-2 active:scale-95">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4"></path></svg>
